<?php
require_once __DIR__.'/../includes/auth.php';
global $conn;
if(empty($_SESSION['customer_portal_authenticated'])||empty($_SESSION['customer_portal_tenant_id'])||empty($_SESSION['customer_portal_customer_id'])){
 header('Location: login.php');exit;
}
$tenantId=(int)$_SESSION['customer_portal_tenant_id'];$customerId=(int)$_SESSION['customer_portal_customer_id'];
$stmt=$conn->prepare("SELECT c.* FROM customers c INNER JOIN customer_portal_users p ON p.customer_id=c.id AND p.tenant_id=c.tenant_id WHERE c.id=? AND c.tenant_id=? AND p.id=? AND p.status='active' LIMIT 1");
if(!$stmt){http_response_code(503);exit('Customer portal is temporarily unavailable.');}
$stmt->bind_param('iii',$customerId,$tenantId,$_SESSION['customer_portal_user_id']);$stmt->execute();$customer=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$customer){unset($_SESSION['customer_portal_authenticated'],$_SESSION['customer_portal_user_id'],$_SESSION['customer_portal_tenant_id'],$_SESSION['customer_portal_customer_id']);header('Location: login.php');exit;}
$accounts=[];$invoices=[];$payments=[];$subscriptions=[];
$q=$conn->prepare("SELECT * FROM internet_accounts WHERE customer_id=? AND tenant_id=? ORDER BY id DESC");
if($q){$q->bind_param('ii',$customerId,$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$accounts[]=$x;$q->close();}
$q=$conn->prepare("SELECT * FROM invoices WHERE customer_id=? AND tenant_id=? ORDER BY id DESC LIMIT 50");
if($q){$q->bind_param('ii',$customerId,$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$invoices[]=$x;$q->close();}
$q=$conn->prepare("SELECT p.* FROM payments p INNER JOIN invoices i ON i.id=p.invoice_id AND i.tenant_id=p.tenant_id WHERE i.customer_id=? AND i.tenant_id=? ORDER BY p.id DESC LIMIT 50");
if($q){$q->bind_param('ii',$customerId,$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$payments[]=$x;$q->close();}
if(flexihubTableHasColumn('service_subscriptions','tenant_id')){
 $q=$conn->prepare("SELECT * FROM service_subscriptions WHERE customer_id=? AND tenant_id=? ORDER BY end_date DESC LIMIT 20");
 if($q){$q->bind_param('ii',$customerId,$tenantId);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$subscriptions[]=$x;$q->close();}
}
$outstanding=0;foreach($invoices as $invoice){$total=(float)($invoice['total_amount']??$invoice['total']??$invoice['amount']??0);$paid=(float)($invoice['actual_paid']??0);$outstanding+=max(0,$total-$paid);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Internet Account</title></head><body><header><div><strong>FLEXIHUB</strong><span>Customer Portal</span></div><form method="post" action="logout.php"><button>Sign Out</button></form></header><main><section class="hero"><div><small>WELCOME BACK</small><h1><?=e(trim(($customer['first_name']??'').' '.($customer['last_name']??'')))?></h1><p>Customer Number: <?=e($customer['customer_number']??'')?> · Account status: <?=e($customer['status']??'')?></p></div><div class="balance"><small>Outstanding Balance</small><strong><?=e(formatMoney($outstanding))?></strong></div></section><section class="metrics"><div><small>Internet Accounts</small><strong><?=count($accounts)?></strong></div><div><small>Invoices</small><strong><?=count($invoices)?></strong></div><div><small>Service Records</small><strong><?=count($subscriptions)?></strong></div><div><small>Payments</small><strong><?=count($payments)?></strong></div></section><section class="panel"><h2>My Internet Services</h2><div class="table-wrap"><table><thead><tr><th>Account</th><th>Package</th><th>Connection</th><th>Status</th><th>Expiry</th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><?=e($a['account_number']??('Account #'.$a['id']))?></td><td><?=e($a['plan_name']??$a['package_name']??'—')?></td><td><?=e($a['connection_type']??'—')?></td><td><?=e($a['status']??'—')?></td><td><?=e($a['expiry_date']??$a['expires_at']??'—')?></td></tr><?php endforeach; ?><?php if(!$accounts): ?><tr><td colspan="5">No internet services are linked to your customer account.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><h2>Invoices</h2><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Due Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i): $total=(float)($i['total_amount']??$i['total']??$i['amount']??0);$paid=(float)($i['actual_paid']??0); ?><tr><td><?=e($i['invoice_number']??('Invoice #'.$i['id']))?></td><td><?=e($i['due_date']??'—')?></td><td><?=e(formatMoney($total))?></td><td><?=e(formatMoney($paid))?></td><td><?=e(formatMoney(max(0,$total-$paid)))?></td><td><?=e($i['status']??'—')?></td></tr><?php endforeach; ?><?php if(!$invoices): ?><tr><td colspan="6">No invoices found.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><h2>Recent Payments</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?=e($p['payment_date']??$p['created_at']??'—')?></td><td><?=e($p['payment_method']??'—')?></td><td><?=e($p['reference']??'—')?></td><td><?=e(formatMoney($p['amount']??0))?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="4">No payments recorded yet.</td></tr><?php endif; ?></tbody></table></div></section><p class="help">For payments, service changes or technical support, please contact your ISP using the contact details on your service agreement.</p></main><style>*{box-sizing:border-box}body{margin:0;background:#080e18;color:#e2e8f0;font-family:Arial,sans-serif}header{display:flex;justify-content:space-between;align-items:center;padding:16px 5%;border-bottom:1px solid rgba(148,163,184,.14);background:#0d1625}header strong{display:block;color:#60a5fa;letter-spacing:.12em}header span{display:block;color:#94a3b8;font-size:11px;margin-top:3px}header button{padding:9px 13px;border:1px solid rgba(148,163,184,.2);border-radius:8px;background:#172235;color:#e2e8f0}main{max-width:1200px;margin:24px auto;padding:0 18px}.hero{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px;border:1px solid rgba(59,130,246,.2);border-radius:16px;background:radial-gradient(circle at 90% 10%,rgba(37,99,235,.2),transparent 35%),linear-gradient(135deg,#101827,#0a101a)}.hero small,.balance small,.metrics small{color:#94a3b8}.hero h1{margin:8px 0;color:#f8fafc}.hero p{color:#94a3b8}.balance strong{display:block;color:#f8fafc;font-size:25px;margin-top:6px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.metrics>div,.panel{padding:18px;border:1px solid rgba(148,163,184,.14);border-radius:14px;background:linear-gradient(145deg,#101827,#0b111b)}.metrics strong{display:block;color:#f8fafc;font-size:22px;margin-top:6px}.panel{margin-bottom:15px}.panel h2{margin:0 0 14px;color:#f8fafc;font-size:17px}.table-wrap{overflow:auto}table{width:100%;min-width:650px;border-collapse:collapse}th,td{padding:11px 12px;border-bottom:1px solid rgba(148,163,184,.13);text-align:left}th{background:#0b111b;color:#94a3b8}td{color:#e2e8f0}.help{color:#94a3b8;margin:20px 0 35px}@media(max-width:700px){.hero{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:repeat(2,1fr)}}
</style></body></html>
